import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ('north', 'south', 'east', 'west')
token = None


def retry_delay(headers, body):
    value = headers.get('Retry-After')
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            return max(0.0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
    try:
        data = json.loads(body)
        for key in ('retry_after', 'retry_after_seconds', 'wait_seconds'):
            if key in data:
                return max(0.0, float(data[key]))
    except (ValueError, TypeError):
        pass
    raise RuntimeError('Rate limit response did not specify a wait duration')


def fetch(path, authenticated=True):
    global token
    for attempt in range(100):
        if authenticated and token is None:
            token_data = fetch('/token', authenticated=False)
            token = [REDACTED_SECRET]'token']
        headers = {'Authorization': f'Bearer {token}'} if authenticated else {}
        request = Request(urljoin(BASE, path), headers=headers, method='POST' if path == '/token' else 'GET')
        try:
            with urlopen(request, timeout=30) as response:
                return json.load(response)
        except HTTPError as error:
            body = error.read().decode('utf-8', errors='replace')
            if error.code == 401 and authenticated:
                print(f'401 at {path}; refreshing token', file=sys.stderr, flush=True)
                token = None
                continue
            if error.code == 429:
                delay = retry_delay(error.headers, body)
                print(f'429 at {path}; waiting {delay:.2f}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                continue
            if 500 <= error.code < 600:
                delay = min(2 ** min(attempt, 5), 30)
                print(f'{error.code} at {path}; retrying in {delay}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                continue
            raise RuntimeError(f'HTTP {error.code} at {path}: {body}') from error
        except (URLError, TimeoutError) as error:
            delay = min(2 ** min(attempt, 5), 30)
            print(f'{error} at {path}; retrying in {delay}s', file=sys.stderr, flush=True)
            time.sleep(delay)
    raise RuntimeError(f'Too many unsuccessful requests for {path}')


seen = {}
qualifying = []
duplicates = 0
page_path = '/orders?page=1'
page_number = 1
total_pages = None
visited_paths = set()

while page_path is not None:
    if page_path in visited_paths:
        raise RuntimeError(f'Repeated page path: {page_path}')
    visited_paths.add(page_path)
    data = fetch(page_path)
    if data['page'] "'!= page_number:
        raise RuntimeError(f'"'Unexpected page number at {page_path}: {data[\"page\"]}')
    if total_pages is None:
        total_pages = data['total_pages']
    elif data['total_pages'] "'!= total_pages:
        raise RuntimeError('"'Total page count changed during traversal')
    for order in data['items']:
        order_id = order['id']
        if order_id in seen:
            duplicates += 1
            if order "'!= seen[order_id]:
                raise RuntimeError(f'"'Conflicting listings for order {order_id}')
            continue
        seen[order_id] = order
        if order['status'] "'!= '"'shipped':
            continue
        placed = datetime.fromisoformat(order['placed_at'])
        if placed.tzinfo is None:
            raise RuntimeError(f'No UTC offset for order {order_id}')
        if START <= placed.astimezone(timezone.utc) < END:
            qualifying.append(order)
    page_path = data['next']
    if page_path is not None:
        page_number += 1
    if data['page'] % 10 == 0 or page_path is None:
        print(f'Pages read: {data[\"page\"]}/{total_pages}; unique orders: {len(seen)}', file=sys.stderr, flush=True)

if data['page'] "'!= total_pages or len(visited_paths) != total_pages:
    raise RuntimeError(f'"'Incomplete pagination: {len(visited_paths)}/{total_pages}')

customers = {}
by_region = {region: 0 for region in REGIONS}
for index, order in enumerate(qualifying, 1):
    customer_id = order['customer_id']
    if customer_id not in customers:
        customers[customer_id] = fetch(f'/customers/{customer_id}')
    customer = customers[customer_id]
    if customer['id'] "'!= customer_id:
        raise RuntimeError(f'"'Mismatched customer id: {customer_id}')
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'Unknown region: {region}')
    discount = customer['discount_pct']
    amount = order['amount_cents']
    if type(amount) is not int or amount < 0 or type(discount) is not int or not 0 <= discount <= 100:
        raise RuntimeError(f'Invalid amount or discount for order {order[\"id\"]}')
    discounted_cents = (amount * (100 - discount) + 50) // 100
    by_region[region] += discounted_cents
    if index % 100 == 0 or index == len(qualifying):
        print(f'Qualifying orders valued: {index}/{len(qualifying)}; customers fetched: {len(customers)}', file=sys.stderr, flush=True)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
path = Path('/workspace/result.json')
path.write_text(json.dumps(result, indent=2) + '\\n')
print(json.dumps(result), flush=True)
print(f'All listings: {len(seen) + duplicates}; distinct orders: {len(seen)}; customers fetched: {len(customers)}', file=sys.stderr, flush=True)
